import { maskFromGrid } from "./blob47.js";
import { dualMaskFromGrid } from "./dual16.js";
import { getTerrainMasks, terrainAtlasCoords } from "./topology.js";
export function gridToMacroPattern(grid, recipe, name, id) {
    const height = grid.length;
    const width = grid[0]?.length ?? 0;
    const cells = [];
    for (let y = 0; y < height; y += 1) {
        for (let x = 0; x < width; x += 1) {
            if (recipe.topology === "blob47" && !grid[y][x])
                continue;
            const mask = recipe.topology === "dual16" ? dualMaskFromGrid(grid, x, y) : maskFromGrid(grid, x, y);
            if (recipe.topology === "dual16" && mask === 0)
                continue;
            cells.push({ x, y, mask });
        }
    }
    return { id, name: name.trim() || "Pattern", width, height, cells };
}
export function analyzePatternRepetition(pattern) {
    if (pattern.cells.length === 0)
        return { cellCount: 0, uniqueMasks: 0, dominantShare: 0, adjacentDuplicateShare: 0, entropy: 0, grade: "repetitive" };
    const counts = new Map();
    const byPosition = new Map(pattern.cells.map((cell) => [`${cell.x}:${cell.y}`, cell]));
    let duplicateEdges = 0;
    let testedEdges = 0;
    for (const cell of pattern.cells) {
        counts.set(cell.mask, (counts.get(cell.mask) ?? 0) + 1);
        for (const [dx, dy] of [[1, 0], [0, 1]]) {
            const neighbor = byPosition.get(`${cell.x + dx}:${cell.y + dy}`);
            if (!neighbor)
                continue;
            testedEdges += 1;
            if (neighbor.mask === cell.mask)
                duplicateEdges += 1;
        }
    }
    const probabilities = [...counts.values()].map((count) => count / pattern.cells.length);
    const entropy = -probabilities.reduce((sum, probability) => sum + probability * Math.log2(probability), 0);
    const dominantShare = Math.max(...counts.values()) / pattern.cells.length;
    const adjacentDuplicateShare = testedEdges ? duplicateEdges / testedEdges : 0;
    const grade = dominantShare > 0.72 || adjacentDuplicateShare > 0.68 ? "repetitive" : dominantShare > 0.5 || adjacentDuplicateShare > 0.45 ? "watch" : "varied";
    return { cellCount: pattern.cells.length, uniqueMasks: counts.size, dominantShare, adjacentDuplicateShare, entropy, grade };
}
export function buildGodotPatternScript(recipe, pattern) {
    const masks = getTerrainMasks(recipe);
    const lines = pattern.cells.flatMap((cell) => {
        const index = masks.indexOf(cell.mask);
        if (index < 0)
            return [];
        const coords = terrainAtlasCoords(recipe, cell.mask, index);
        return [`\tpattern.set_cell(Vector2i(${cell.x}, ${cell.y}), source_id, Vector2i(${coords.x}, ${coords.y}), 0)`];
    });
    return `# Generated by Tesserae.\nclass_name TesseraePattern_${pattern.id.replace(/[^a-zA-Z0-9_]/g, "_")}\n\nstatic func build(source_id: int) -> TileMapPattern:\n\tvar pattern := TileMapPattern.new()\n${lines.join("\n")}\n\treturn pattern\n`;
}
